"""Inputs for the `fn/ApplyMoverSettings` unit.

The oracle runs `0x140c862e0` against an arena-pinned asset whose three pointer
fields point at the scale pair, the gate bytes and the id array. The probe
receives those three blocks directly. Cases cycle four ways:

* null state record, count 0 (vector untouched);
* the transform record A (bitmap 2), count 3;
* null state record, count 8 (the inline capacity boundary);
* the record C with bitmap 1 (bit 1 clear), count 1: the masked decode is zero,
  so the client takes the direct-copy path for `+0x490..+0x498`.

The settings object is pre-filled with random bytes except its vector header
(`+0x10 = base + 0x20`, `+0x18 = 0`, `+0x1c = 0x80000008`), so every byte the
apply does not write must survive on both sides.
"""

from __future__ import annotations

import random
import struct
from typing import List

from emu_oracle import ARENA_BASE, ArgSpec

GLOBAL = 0x00007ff7c8899598
REC_A = 0x00007ff7c8899d58
REC_C = 0x00007ff7c8899e98
DECODE_BYTE = 0x42

OUT_OFF = 0x4000
ASSET_OFF = 0x5000
SCALES_OFF = 0x5200
GATES_OFF = 0x5300
IDS_OFF = 0x5400
OUT_LEN = 0x700
ASSET_LEN = 0x140

BASE = ARENA_BASE + OUT_OFF
SCALES = ARENA_BASE + SCALES_OFF
GATES = ARENA_BASE + GATES_OFF
IDS = ARENA_BASE + IDS_OFF

STATE_HEX = ""


def _out(i: int) -> bytes:
    rng = random.Random(0x4150_504C ^ i)
    buf = bytearray(rng.getrandbits(8) for _ in range(OUT_LEN))
    struct.pack_into("<Q", buf, 0x10, BASE + 0x20)
    struct.pack_into("<i", buf, 0x18, 0)
    struct.pack_into("<I", buf, 0x1C, 0x80000008)
    return bytes(buf)


def _case(i: int):
    variant = i % 4
    if variant == 0:
        return 0, 0x00, 0
    if variant == 1:
        return 3, REC_A, 1
    if variant == 2:
        return 8, 0x00, 2
    return 1, REC_C, 3


def make_args(i: int) -> List[ArgSpec]:
    count, record, shape = _case(i)
    rng = random.Random(0x5345_5454 ^ i)
    asset = bytearray(rng.getrandbits(8) for _ in range(ASSET_LEN))
    struct.pack_into("<Q", asset, 0x100, SCALES)
    struct.pack_into("<Q", asset, 0xD0, GATES)
    struct.pack_into("<Q", asset, 0x118, IDS)
    struct.pack_into("<i", asset, 0x120, count)
    if shape == 1:
        struct.pack_into("<H", asset, 0xF2, 0)
    elif shape == 2:
        struct.pack_into("<H", asset, 0xF2, 0x1234)
    else:
        struct.pack_into("<H", asset, 0xF2, 1)
    scales = struct.pack("<2I", rng.getrandbits(32), rng.getrandbits(32))
    gates = bytes(rng.getrandbits(8) for _ in range(4))
    ids = b"".join(struct.pack("<I", rng.getrandbits(32)) for _ in range(8))
    state = bytes.fromhex(STATE_HEX) if record else b""
    return [
        ArgSpec(kind="ptr", mem=_out(i), arena_offset=OUT_OFF),
        ArgSpec(kind="ptr", mem=bytes(asset), arena_offset=ASSET_OFF),
        ArgSpec(kind="u64", bits=record),
        ArgSpec(kind="u64", bits=BASE),
        ArgSpec(kind="ptr", mem=scales, arena_offset=SCALES_OFF),
        ArgSpec(kind="ptr", mem=gates, arena_offset=GATES_OFF),
        ArgSpec(kind="ptr", mem=ids, arena_offset=IDS_OFF),
        ArgSpec(kind="ptr", mem=state),
        ArgSpec(kind="u64", bits=GLOBAL),
        ArgSpec(kind="u64", bits=0),
        ArgSpec(kind="u64", bits=DECODE_BYTE),
        ArgSpec(kind="u64", bits=0),
    ]
